"""Builds Linux apps: a .deb package (Debian/Ubuntu/Mint/Pop!_OS...) and a portable
self-extracting .run file that works on any distro. Written in pure Python, so it
works from Windows too."""
import gzip
import io
import re
import tarfile
import time

LAUNCHER = r'''#!/bin/sh
# %%NAME%% - launcher generated by chimiPack
APPDIR="$(dirname "$(readlink -f "$0")")"
WWW="$APPDIR/www"
ENTRY='%%ENTRY%%'
APPID='%%APPID%%'
PORT=%%PORT%%
W=%%WIDTH%%; H=%%HEIGHT%%
DATA="${XDG_DATA_HOME:-$HOME/.local/share}/chimipack/$APPID"
OLD_DATA="${XDG_DATA_HOME:-$HOME/.local/share}/html2app/$APPID"   # name before the chimiPack rebrand
if [ -d "$OLD_DATA" ] && [ ! -e "$DATA" ]; then mkdir -p "$(dirname "$DATA")" && mv "$OLD_DATA" "$DATA"; fi
mkdir -p "$DATA"
URL="file://$WWW/$ENTRY"
SERVER=""

if command -v python3 >/dev/null 2>&1; then
  rm -f "$DATA/port"
  python3 "$APPDIR/serve.py" "$WWW" "$PORT" "$DATA/port" &
  SERVER=$!
  i=0; while [ ! -s "$DATA/port" ] && [ $i -lt 50 ]; do sleep 0.1; i=$((i+1)); done
  if [ -s "$DATA/port" ]; then URL="http://127.0.0.1:$(cat "$DATA/port")/$ENTRY"; fi
fi

cleanup() { [ -n "$SERVER" ] && kill "$SERVER" 2>/dev/null; }
trap cleanup EXIT INT TERM

FS=""; [ "%%FULLSCREEN%%" = "1" ] && FS="--start-fullscreen"
for b in microsoft-edge microsoft-edge-stable google-chrome google-chrome-stable chromium chromium-browser brave-browser vivaldi; do
  if command -v "$b" >/dev/null 2>&1; then
    PROFILE="$DATA/profile"
    case "$(readlink -f "$(command -v "$b")")" in
      /snap/*) PROFILE="$HOME/snap/$(basename "$b")/common/chimipack-$APPID"; mkdir -p "$PROFILE";;
    esac
    "$b" --app="$URL" --user-data-dir="$PROFILE" --class="$APPID" --window-size=$W,$H \
      --no-first-run --no-default-browser-check --autoplay-policy=no-user-gesture-required $FS >/dev/null 2>&1
    exit 0
  fi
done
if command -v flatpak >/dev/null 2>&1; then
  for f in com.google.Chrome org.chromium.Chromium com.microsoft.Edge com.brave.Browser; do
    if flatpak info "$f" >/dev/null 2>&1; then
      flatpak run "$f" --app="$URL" --user-data-dir="$DATA/flatpak-profile" --class="$APPID" \
        --window-size=$W,$H --no-first-run --no-default-browser-check $FS >/dev/null 2>&1
      exit 0
    fi
  done
fi
if command -v firefox >/dev/null 2>&1; then
  mkdir -p "$DATA/firefox"
  firefox --new-instance --profile "$DATA/firefox" "$URL" >/dev/null 2>&1
  exit 0
fi
xdg-open "$URL"
[ -n "$SERVER" ] && wait "$SERVER"
'''

SERVER = r'''import http.server, os, socket, sys, functools
root, port, portfile = sys.argv[1], int(sys.argv[2]), sys.argv[3]
class H(http.server.SimpleHTTPRequestHandler):
    extensions_map = dict(http.server.SimpleHTTPRequestHandler.extensions_map, **{
        ".js": "text/javascript", ".mjs": "text/javascript", ".wasm": "application/wasm", ".json": "application/json",
        ".css": "text/css", ".svg": "image/svg+xml", ".webp": "image/webp", ".woff2": "font/woff2"})
    def log_message(self, *a): pass
    def end_headers(self):
        self.send_header("Cache-Control", "no-cache"); super().end_headers()
handler = functools.partial(H, directory=root)
try:
    srv = http.server.ThreadingHTTPServer(("127.0.0.1", port), handler)
except OSError:
    srv = http.server.ThreadingHTTPServer(("127.0.0.1", 0), handler)
with open(portfile, "w") as f: f.write(str(srv.server_address[1]))
srv.serve_forever()
'''

DESKTOP = """[Desktop Entry]
Type=Application
Name=%%NAME%%
Comment=%%NAME%% (made with chimiPack)
Exec=%%EXEC%%
Icon=%%ICON%%
Terminal=false
Categories=%%CATEGORY%%;
StartupWMClass=%%APPID%%
"""

RUN_HEADER = r'''#!/bin/sh
# %%NAME%% - portable Linux app made with chimiPack.
# Run it with:  chmod +x "%%FILE%%" && ./"%%FILE%%"     (add --install to put it in your app menu)
APPID='%%APPID%%'; VERSION='%%VERSION%%'
DEST="${XDG_DATA_HOME:-$HOME/.local/share}/chimipack/$APPID/app"
SELF="$(readlink -f "$0")"
if [ ! -f "$DEST/.version" ] || [ "$(cat "$DEST/.version")" != "$VERSION-%%STAMP%%" ]; then
  rm -rf "$DEST"; mkdir -p "$DEST"
  tail -n +%%LINE%% "$SELF" | tar xzf - -C "$DEST" || { echo "Extraction failed"; exit 1; }
  echo "$VERSION-%%STAMP%%" > "$DEST/.version"
fi
if [ "$1" = "--install" ]; then
  APPS="${XDG_DATA_HOME:-$HOME/.local/share}/applications"; mkdir -p "$APPS"
  sed -e "s|^Exec=.*|Exec=\"$SELF\"|" -e "s|^Icon=.*|Icon=$DEST/icon.png|" "$DEST/app.desktop" > "$APPS/$APPID.desktop"
  echo "Installed to your applications menu."
  exit 0
fi
exec "$DEST/launch.sh" "$@"
exit 0
__CHIMIPACK_PAYLOAD__
'''


def deb_name(package):
    n = re.sub(r"[^a-z0-9.+-]", "-", package.lower()).strip("-.")
    return n if len(n) >= 2 else "chimipack-" + n


def _fill(t, cfg, **extra):
    vals = {"NAME": cfg["name"].replace("\n", " "), "ENTRY": cfg["entry"].replace("'", ""),
            "APPID": cfg["package"], "PORT": str(20000 + sum(map(ord, cfg["package"])) * 7 % 40000),
            "WIDTH": str(int(cfg.get("width", 1200))), "HEIGHT": str(int(cfg.get("height", 800))),
            "FULLSCREEN": "1" if cfg.get("fullscreen") else "0", "VERSION": cfg["version"],
            "CATEGORY": cfg.get("category", "Utility")}
    vals.update(extra)
    for k, v in vals.items():
        t = t.replace("%%" + k + "%%", v)
    return t


def _add(tar, name, data, mode=0o644, mtime=None):
    if isinstance(data, str):
        data = data.encode("utf-8")
    ti = tarfile.TarInfo(name)
    ti.size, ti.mode, ti.mtime = len(data), mode, mtime or int(time.time())
    ti.uid = ti.gid = 0
    ti.uname = ti.gname = "root"
    tar.addfile(ti, io.BytesIO(data))


def _add_dir(tar, name, seen):
    prefix = "./" if name.startswith("./") else ""
    parts = name[len(prefix):].strip("/").split("/")
    for i in range(1, len(parts) + 1):
        d = prefix + "/".join(parts[:i])
        if d in seen:
            continue
        seen.add(d)
        ti = tarfile.TarInfo(d)
        ti.type, ti.mode, ti.mtime = tarfile.DIRTYPE, 0o755, int(time.time())
        ti.uname = ti.gname = "root"
        tar.addfile(ti)


def _app_tree(cfg, files, icon_set):
    """Yields (relative_path, bytes, mode) for the app directory."""
    yield "launch.sh", _fill(LAUNCHER, cfg), 0o755
    yield "serve.py", SERVER, 0o644
    for rel, full in sorted(files.items()):
        with open(full, "rb") as f:
            yield "www/" + rel, f.read(), 0o644
    if icon_set:
        yield "icon.png", icon_set.get(256) or icon_set[max(icon_set)], 0o644


def _ar(members):
    out = bytearray(b"!<arch>\n")
    for name, data in members:
        hdr = f"{name:<16}{int(time.time()):<12}{0:<6}{0:<6}{'100644':<8}{len(data):<10}`\n".encode()
        out += hdr + data
        if len(data) % 2:
            out += b"\n"
    return bytes(out)


def build_deb(cfg, files, icon_set, out_path, log=print):
    pkg = deb_name(cfg["package"].split(".")[-1] if cfg.get("short_deb") else cfg["package"])
    base = f"opt/{pkg}"
    data_io = io.BytesIO()
    installed = 0
    with tarfile.open(fileobj=data_io, mode="w:gz", format=tarfile.GNU_FORMAT) as tar:
        seen = set()
        for rel, data, mode in _app_tree(cfg, files, icon_set):
            if isinstance(data, str):
                data = data.encode("utf-8")
            path = f"{base}/{rel}"
            _add_dir(tar, "./" + path.rsplit("/", 1)[0], seen)
            _add(tar, "./" + path, data, mode)
            installed += len(data)
        _add_dir(tar, "./usr/bin", seen)
        link = tarfile.TarInfo("./usr/bin/" + pkg)
        link.type, link.linkname, link.mode = tarfile.SYMTYPE, f"/{base}/launch.sh", 0o777
        link.uname = link.gname = "root"
        tar.addfile(link)
        _add_dir(tar, "./usr/share/applications", seen)
        _add(tar, f"./usr/share/applications/{pkg}.desktop",
             _fill(DESKTOP, cfg, EXEC=f"/usr/bin/{pkg}", ICON=pkg if icon_set else "applications-internet"))
        if icon_set:
            for s in (48, 128, 256, 512):
                if s in icon_set:
                    d = f"./usr/share/icons/hicolor/{s}x{s}/apps"
                    _add_dir(tar, d, seen)
                    _add(tar, f"{d}/{pkg}.png", icon_set[s])
    version = re.sub(r"[^0-9A-Za-z.+~-]", "", cfg["version"]) or "1.0"
    if not version[0].isdigit():
        version = "1.0"
    control = (f"Package: {pkg}\nVersion: {version}\nArchitecture: all\n"
               f"Maintainer: {cfg.get('publisher') or 'chimiPack user'} <noreply@example.com>\n"
               f"Installed-Size: {installed // 1024 + 1}\nRecommends: python3\nSection: web\nPriority: optional\n"
               f"Description: {cfg['name']}\n {cfg['name']} desktop app made with chimiPack.\n")
    ctrl_io = io.BytesIO()
    with tarfile.open(fileobj=ctrl_io, mode="w:gz", format=tarfile.GNU_FORMAT) as tar:
        _add(tar, "./control", control)
    with open(out_path, "wb") as f:
        f.write(_ar([("debian-binary", b"2.0\n"), ("control.tar.gz", ctrl_io.getvalue()),
                     ("data.tar.gz", data_io.getvalue())]))
    return out_path


def build_run(cfg, files, icon_set, out_path, log=print):
    import os
    payload = io.BytesIO()
    with tarfile.open(fileobj=payload, mode="w:gz", format=tarfile.GNU_FORMAT) as tar:
        seen = set()
        for rel, data, mode in _app_tree(cfg, files, icon_set):
            if isinstance(data, str):
                data = data.encode("utf-8")
            if "/" in rel:
                _add_dir(tar, rel.rsplit("/", 1)[0], seen)
            _add(tar, rel, data, mode)
        _add(tar, "app.desktop", _fill(DESKTOP, cfg, EXEC="launch.sh", ICON="icon"))
    header = _fill(RUN_HEADER, cfg, FILE=os.path.basename(out_path), STAMP=str(int(time.time())))
    header = header.replace("%%LINE%%", str(header.count("\n") + 1))
    with open(out_path, "wb") as f:
        f.write(header.encode("utf-8") + payload.getvalue())
    return out_path
